-- Scoring v2: preserve native counters before converting existing records once.
ALTER TABLE play_sessions ADD COLUMN score_version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE play_sessions ADD COLUMN mode_id TEXT NOT NULL DEFAULT 'legacy';
ALTER TABLE score_submissions ADD COLUMN raw_score INTEGER;
ALTER TABLE score_submissions ADD COLUMN source_version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE score_submissions ADD COLUMN mode_id TEXT NOT NULL DEFAULT 'legacy';
UPDATE score_submissions SET raw_score=score;
UPDATE score_submissions SET score = CASE game_id
  WHEN 'orbit' THEN CAST((CASE WHEN raw_score<=1500 THEN 1000.0*raw_score/1500 WHEN raw_score<=6500 THEN 1000+2000.0*(raw_score-1500)/5000 WHEN raw_score<=18000 THEN 3000+3000.0*(raw_score-6500)/11500 ELSE 6000+2000*log2(1.0*raw_score/18000) END)+1e-7 AS INTEGER)
  WHEN 'stack' THEN CAST((CASE WHEN raw_score<=12 THEN 1000.0*raw_score/12 WHEN raw_score<=45 THEN 1000+2000.0*(raw_score-12)/33 WHEN raw_score<=120 THEN 3000+3000.0*(raw_score-45)/75 ELSE 6000+2000*log2(1.0*raw_score/120) END)+1e-7 AS INTEGER)
  WHEN 'reaction' THEN CAST((CASE WHEN raw_score<=4500 THEN 1000.0*raw_score/4500 WHEN raw_score<=14000 THEN 1000+2000.0*(raw_score-4500)/9500 WHEN raw_score<=24000 THEN 3000+3000.0*(raw_score-14000)/10000 ELSE 6000+2000*log2(1.0*raw_score/24000) END)+1e-7 AS INTEGER)
  WHEN 'dodge' THEN CAST((CASE WHEN raw_score<=3500 THEN 1000.0*raw_score/3500 WHEN raw_score<=14000 THEN 1000+2000.0*(raw_score-3500)/10500 WHEN raw_score<=40000 THEN 3000+3000.0*(raw_score-14000)/26000 ELSE 6000+2000*log2(1.0*raw_score/40000) END)+1e-7 AS INTEGER)
  WHEN 'pulse' THEN CAST((CASE WHEN raw_score<=30000 THEN 1000.0*raw_score/30000 WHEN raw_score<=200000 THEN 1000+2000.0*(raw_score-30000)/170000 WHEN raw_score<=650000 THEN 3000+3000.0*(raw_score-200000)/450000 ELSE 6000+2000*log2(1.0*raw_score/650000) END)+1e-7 AS INTEGER)
