  WHEN 'typerush' THEN CAST((CASE WHEN raw_score<=10000 THEN 1000.0*raw_score/10000 WHEN raw_score<=100000 THEN 1000+2000.0*(raw_score-10000)/90000 WHEN raw_score<=350000 THEN 3000+3000.0*(raw_score-100000)/250000 ELSE 6000+2000*log2(1.0*raw_score/350000) END)+1e-7 AS INTEGER)
  WHEN 'oneline' THEN CAST((CASE WHEN raw_score<=3000 THEN 1000.0*raw_score/3000 WHEN raw_score<=14000 THEN 1000+2000.0*(raw_score-3000)/11000 WHEN raw_score<=40000 THEN 3000+3000.0*(raw_score-14000)/26000 ELSE 6000+2000*log2(1.0*raw_score/40000) END)+1e-7 AS INTEGER)
  WHEN 'breakout' THEN CAST((CASE WHEN raw_score<=5000 THEN 1000.0*raw_score/5000 WHEN raw_score<=25000 THEN 1000+2000.0*(raw_score-5000)/20000 WHEN raw_score<=90000 THEN 3000+3000.0*(raw_score-25000)/65000 ELSE 6000+2000*log2(1.0*raw_score/90000) END)+1e-7 AS INTEGER)
