  WHEN 'chain' THEN CAST((CASE WHEN raw_score<=25000 THEN 1000.0*raw_score/25000 WHEN raw_score<=350000 THEN 1000+2000.0*(raw_score-25000)/325000 WHEN raw_score<=1400000 THEN 3000+3000.0*(raw_score-350000)/1050000 ELSE 6000+2000*log2(1.0*raw_score/1400000) END)+1e-7 AS INTEGER)
  WHEN 'gravity' THEN CAST((CASE WHEN raw_score<=2500 THEN 1000.0*raw_score/2500 WHEN raw_score<=8500 THEN 1000+2000.0*(raw_score-2500)/6000 WHEN raw_score<=16000 THEN 3000+3000.0*(raw_score-8500)/7500 ELSE 6000+2000*log2(1.0*raw_score/16000) END)+1e-7 AS INTEGER)
